import numpy as np


def construct(budget_seconds, start):
    """Code Zero: keep the start if there is one, otherwise 32 small equal circles on a grid."""
    if start is not None:
        return np.asarray(start, dtype=float)
    k = int(np.ceil(np.sqrt(32)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:32]
    return np.array([[x, y, 0.02] for x, y in pts])

import numpy as np
from scipy.optimize import minimize
import time


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    # 4x8 grid init
    pts = []
    for j in range(4):
        for i in range(8):
            pts.append(((i + 0.5) / 8.0, (j + 0.5) / 4.0))
    pts = np.array(pts[:n])
    r0 = 0.06
    z0 = np.zeros(3 * n)
    for k in range(n):
        z0[3 * k] = pts[k, 0]
        z0[3 * k + 1] = pts[k, 1]
        z0[3 * k + 2] = r0

    def unpack(z):
        return z[0::3], z[1::3], z[2::3]

    def obj(z):
        return -np.sum(z[2::3])

    def obj_grad(z):
        g = np.zeros_like(z)
        g[2::3] = -1.0
        return g

    bounds = []
    for k in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-6, 0.5))

    cons = []
    # wall constraints
    for k in range(n):
        def make_wall(k, which):
            def f(z):
                x, y, r = z[3*k], z[3*k+1], z[3*k+2]
                if which == 0:
                    return x - r
                elif which == 1:
                    return 1.0 - x - r
                elif which == 2:
                    return y - r
                else:
                    return 1.0 - y - r
            return f
        for w in range(4):
            cons.append({'type': 'ineq', 'fun': make_wall(k, w)})

    # pair constraints
    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(z):
                    xi, yi, ri = z[3*i], z[3*i+1], z[3*i+2]
                    xj, yj, rj = z[3*j], z[3*j+1], z[3*j+2]
                    return (xi - xj)**2 + (yi - yj)**2 - (ri + rj)**2
                return f
            cons.append({'type': 'ineq', 'fun': make_pair(i, j)})

    try:
        res = minimize(obj, z0, jac=obj_grad, method='SLSQP', bounds=bounds,
                       constraints=cons, options={'maxiter': 500, 'ftol': 1e-12})
        z = res.x
    except Exception:
        z = z0

    x, y, r = unpack(z)
    r = r - 1e-8
    r = np.maximum(r, 1e-7)

    # clamp inside
    x = np.clip(x, r, 1.0 - r)
    y = np.clip(y, r, 1.0 - r)

    # fix overlaps by shrinking
    for _ in range(50):
        bad = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(x[i] - x[j], y[i] - y[j])
                s = r[i] + r[j]
                if d < s:
                    bad = True
                    excess = s - d
                    r[i] = max(r[i] - excess * 0.5 - 1e-9, 1e-7)
                    r[j] = max(r[j] - excess * 0.5 - 1e-9, 1e-7)
        # wall check
        for i in range(n):
            if x[i] - r[i] < 0 or x[i] + r[i] > 1 or y[i] - r[i] < 0 or y[i] + r[i] > 1:
                bad = True
                r[i] = max(r[i] - 1e-9, 1e-7)
                x[i] = np.clip(x[i], r[i], 1.0 - r[i])
                y[i] = np.clip(y[i], r[i], 1.0 - r[i])
        if not bad:
            break

    out = np.zeros((n, 3))
    out[:, 0] = x
    out[:, 1] = y
    out[:, 2] = r
    return out

import numpy as np
import time


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32

    # Initial 6x6 grid minus four corners, r=0.07
    coords = []
    for j in range(6):
        for i in range(6):
            if (i in (0, 5)) and (j in (0, 5)):
                continue
            coords.append(((i + 0.5) / 6.0, (j + 0.5) / 6.0))
    coords = coords[:n]
    pos = np.array(coords, dtype=float)
    r = np.full(n, 0.07)

    def relax(pos, r, sweeps):
        for _ in range(sweeps):
            # pairwise overlap resolution
            for i in range(n - 1):
                xi, yi = pos[i]
                for j in range(i + 1, n):
                    dx = pos[j, 0] - xi
                    dy = pos[j, 1] - yi
                    d2 = dx * dx + dy * dy
                    rs = r[i] + r[j]
                    if d2 < rs * rs:
                        d = np.sqrt(d2) if d2 > 0 else 1e-12
                        if d < 1e-12:
                            dx, dy, d = 1e-6, 0.0, 1e-6
                        ov = rs - d
                        ux, uy = dx / d, dy / d
                        pos[i, 0] -= 0.5 * ov * ux
                        pos[i, 1] -= 0.5 * ov * uy
                        pos[j, 0] += 0.5 * ov * ux
                        pos[j, 1] += 0.5 * ov * uy
                        xi, yi = pos[i]
            # clamp
            for i in range(n):
                ri = r[i]
                pos[i, 0] = min(max(pos[i, 0], ri), 1.0 - ri)
                pos[i, 1] = min(max(pos[i, 1], ri), 1.0 - ri)

    def has_overlap(pos, r):
        for i in range(n - 1):
            for j in range(i + 1, n):
                dx = pos[j, 0] - pos[i, 0]
                dy = pos[j, 1] - pos[i, 1]
                rs = r[i] + r[j]
                if dx * dx + dy * dy < rs * rs - 1e-15:
                    return True
        return False

    # Equal-radius inflation
    for step in range(300):
        if time.process_time() - t0 > budget_seconds * 0.55:
            break
        r_new = r + 0.0005
        # check wall feasibility
        if np.any(r_new > 0.5):
            break
        relax(pos, r_new, 80)
        if has_overlap(pos, r_new):
            # revert
            relax(pos, r, 20)
        else:
            r = r_new

    # Variable radius growth
    for sweep in range(200):
        if time.process_time() - t0 > budget_seconds * 0.85:
            break
        for i in range(n):
            xi, yi = pos[i]
            lim = min(xi, 1.0 - xi, yi, 1.0 - yi)
            for j in range(n):
                if j == i:
                    continue
                dx = pos[j, 0] - xi
                dy = pos[j, 1] - yi
                d = np.sqrt(dx * dx + dy * dy)
                lim = min(lim, d - r[j])
            if lim > 0:
                r[i] = lim - 1e-9

    # Safety shrink
    r = r - 1e-8
    r = np.maximum(r, 1e-6)

    out = np.column_stack([pos, r])
    return out

import numpy as np
import time
import math
from scipy.optimize import minimize, linprog, least_squares


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.9
    n = 32

    def feasible(c, tol=0.0):
        x = c[:, 0]; y = c[:, 1]; r = c[:, 2]
        if np.any(r <= 0):
            return False
        if np.any(x - r < -tol) or np.any(x + r > 1 + tol) or \
           np.any(y - r < -tol) or np.any(y + r > 1 + tol):
            return False
        dx = x[:, None] - x[None, :]
        dy = y[:, None] - y[None, :]
        d2 = dx * dx + dy * dy
        rs = r[:, None] + r[None, :]
        np.fill_diagonal(d2, 1e9)
        if np.any(d2 < rs * rs - tol):
            return False
        return True

    def relax(c, sweeps=30):
        c = c.copy()
        for _ in range(sweeps):
            x = c[:, 0].copy(); y = c[:, 1].copy(); r = c[:, 2].copy()
            for i in range(n):
                for j in range(i + 1, n):
                    dx = x[j] - x[i]; dy = y[j] - y[i]
                    d = math.hypot(dx, dy)
                    need = r[i] + r[j]
                    if d < need and d > 1e-12:
                        push = (need - d) * 0.5
                        ux = dx / d; uy = dy / d
                        x[i] -= ux * push; y[i] -= uy * push
                        x[j] += ux * push; y[j] += uy * push
            for i in range(n):
                ri = r[i]
                if x[i] < ri: x[i] = ri
                elif x[i] > 1 - ri: x[i] = 1 - ri
                if y[i] < ri: y[i] = ri
                elif y[i] > 1 - ri: y[i] = 1 - ri
            c[:, 0] = x; c[:, 1] = y
        return c

    if start is not None:
        cfg = np.array(start, dtype=float).copy()
    else:
        pts = []
        for j in range(4):
            for i in range(8):
                pts.append([(i + 0.5) / 8.0, (j + 0.5) / 4.0, 0.05])
        cfg = np.array(pts, dtype=float)

    if not feasible(cfg):
        cfg = relax(cfg, 50)
    best = cfg.copy()
    best_score = best[:, 2].sum() if feasible(best) else -1e9

    def unpack(z):
        return z[0::3], z[1::3], z[2::3]

    def cons_fun(z):
        x, y, r = unpack(z)
        cons = []
        cons.append(x - r)
        cons.append(1 - x - r)
        cons.append(y - r)
        cons.append(1 - y - r)
        dx = x[:, None] - x[None, :]
        dy = y[:, None] - y[None, :]
        d2 = dx * dx + dy * dy
        rs = r[:, None] + r[None, :]
        iu = np.triu_indices(n, 1)
        cons.append(d2[iu] - rs[iu] ** 2)
        return np.concatenate(cons)

    def cons_jac(z):
        x, y, r = unpack(z)
        nz = 3 * n
        J = np.zeros((4 * n + n * (n - 1) // 2, nz))
        for i in range(n):
            J[i, 3 * i] = 1.0; J[i, 3 * i + 2] = -1.0
            J[n + i, 3 * i] = -1.0; J[n + i, 3 * i + 2] = -1.0
            J[2 * n + i, 3 * i + 1] = 1.0; J[2 * n + i, 3 * i + 2] = -1.0
            J[3 * n + i, 3 * i + 1] = -1.0; J[3 * n + i, 3 * i + 2] = -1.0
        row = 4 * n
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[i] - x[j]; dy = y[i] - y[j]
                ri = r[i]; rj = r[j]
                J[row, 3 * i] = 2 * dx
                J[row, 3 * i + 1] = 2 * dy
                J[row, 3 * i + 2] = -2 * (ri + rj)
                J[row, 3 * j] = -2 * dx
                J[row, 3 * j + 1] = -2 * dy
                J[row, 3 * j + 2] = -2 * (ri + rj)
                row += 1
        return J

    bounds = [(0.0, 1.0)] * (3 * n)
    for i in range(n):
        bounds[3 * i + 2] = (1e-6, 0.5)

    constraints = [{'type': 'ineq', 'fun': cons_fun, 'jac': cons_jac}]

    def run_slsqp(cfg_in, weights, maxiter):
        z0 = np.empty(3 * n)
        z0[0::3] = cfg_in[:, 0]
        z0[1::3] = cfg_in[:, 1]
        z0[2::3] = cfg_in[:, 2]

        def obj(z):
            return -np.dot(weights, z[2::3])

        def obj_grad(z):
            g = np.zeros_like(z)
            g[2::3] = -weights
            return g

        try:
            res = minimize(obj, z0, jac=obj_grad, method='SLSQP',
                           bounds=bounds, constraints=constraints,
                           options={'maxiter': maxiter, 'ftol': 1e-12})
            zr = res.x
            return np.column_stack([zr[0::3], zr[1::3], zr[2::3]])
        except Exception:
            return None

    def solve_lp_radii(xy):
        x = xy[:, 0]; y = xy[:, 1]
        nrows = 4 * n + n * (n - 1) // 2
        A = np.zeros((nrows, n))
        b = np.zeros(nrows)
        row = 0
        for i in range(n):
            A[row, i] = 1.0; b[row] = x[i]; row += 1
        for i in range(n):
            A[row, i] = 1.0; b[row] = 1.0 - x[i]; row += 1
        for i in range(n):
            A[row, i] = 1.0; b[row] = y[i]; row += 1
        for i in range(n):
            A[row, i] = 1.0; b[row] = 1.0 - y[i]; row += 1
        for i in range(n):
            for j in range(i + 1, n):
                d = math.hypot(x[i] - x[j], y[i] - y[j])
                A[row, i] = 1.0; A[row, j] = 1.0; b[row] = d
                row += 1
        c = -np.ones(n)
        try:
            res = linprog(c, A_ub=A, b_ub=b, bounds=[(0, None)] * n,
                          method='highs')
            if not res.success:
                return None
            return res.x
        except Exception:
            return None

    # ---------- initial SLSQP polish ----------
    ones = np.ones(n)
    cand = run_slsqp(best, ones, 150)
    if cand is not None:
        c2 = cand.copy()
        c2[:, 2] -= 1e-9
        if feasible(c2) and c2[:, 2].sum() > best_score:
            best = c2.copy()
            best_score = c2[:, 2].sum()

    # ---------- population search on centres ----------
    rng = np.random.default_rng(12345)

    def make_member(xy):
        r = solve_lp_radii(xy)
        if r is None:
            return None
        cand = np.column_stack([xy[:, 0], xy[:, 1], r])
        pol = run_slsqp(cand, ones, 120)
        if pol is None:
            pol = cand
        c2 = pol.copy()
        c2[:, 2] -= 1e-9
        if not feasible(c2):
            return None
        return c2

    pop = []
    pop.append(best.copy())
    for sigma in (0.01, 0.03, 0.06):
        for _ in range(3):
            if time.process_time() >= deadline:
                break
            xy = best[:, :2].copy()
            xy += rng.normal(0.0, sigma, size=xy.shape)
            xy[:, 0] = np.clip(xy[:, 0], 0.0, 1.0)
            xy[:, 1] = np.clip(xy[:, 1], 0.0, 1.0)
            m = make_member(xy)
            if m is not None:
                pop.append(m)
    for _ in range(2):
        if time.process_time() >= deadline:
            break
        xy = rng.uniform(0.0, 1.0, size=(n, 2))
        m = make_member(xy)
        if m is not None:
            pop.append(m)

    def score_of(c):
        return c[:, 2].sum() if c is not None else -1e9

    while len(pop) < 12 and time.process_time() < deadline:
        xy = best[:, :2].copy()
        xy += rng.normal(0.0, 0.03, size=xy.shape)
        xy[:, 0] = np.clip(xy[:, 0], 0.0, 1.0)
        xy[:, 1] = np.clip(xy[:, 1], 0.0, 1.0)
        m = make_member(xy)
        if m is not None:
            pop.append(m)
        else:
            pop.append(best.copy())

    pop = pop[:12]
    while len(pop) < 12:
        pop.append(best.copy())

    scores = [score_of(c) for c in pop]
    bi = int(np.argmax(scores))
    if scores[bi] > best_score:
        best = pop[bi].copy()
        best_score = scores[bi]

    def tournament():
        i = rng.integers(0, len(pop))
        j = rng.integers(0, len(pop))
        return i if scores[i] >= scores[j] else j

    # ---------- contact-graph recombination helpers ----------
    def contact_edges(c, tol=1e-5):
        x = c[:, 0]; y = c[:, 1]; r = c[:, 2]
        edges = set()
        for i in range(n):
            for j in range(i + 1, n):
                d = math.hypot(x[i] - x[j], y[i] - y[j])
                if d < r[i] + r[j] + tol:
                    edges.add((i, j))
        return edges

    def wall_equalities(c, tol=1e-5):
        x = c[:, 0]; y = c[:, 1]; r = c[:, 2]
        walls = []
        for i in range(n):
            if x[i] - r[i] < tol:
                walls.append((i, 'L'))
            if 1.0 - x[i] - r[i] < tol:
                walls.append((i, 'R'))
            if y[i] - r[i] < tol:
                walls.append((i, 'B'))
            if 1.0 - y[i] - r[i] < tol:
                walls.append((i, 'T'))
        return walls

    def build_from_graph(edges, walls, seed_cfg):
        z0 = np.empty(3 * n)
        z0[0::3] = seed_cfg[:, 0]
        z0[1::3] = seed_cfg[:, 1]
        z0[2::3] = seed_cfg[:, 2]

        def resid(z):
            x = z[0::3]; y = z[1::3]; r = z[2::3]
            out = []
            for (i, j) in edges:
                d = math.hypot(x[i] - x[j], y[i] - y[j])
                out.append(d - (r[i] + r[j]))
            for (i, w) in walls:
                if w == 'L':
                    out.append(x[i] - r[i])
                elif w == 'R':
                    out.append(1.0 - x[i] - r[i])
                elif w == 'B':
                    out.append(y[i] - r[i])
                else:
                    out.append(1.0 - y[i] - r[i])
            if not out:
                out.append(0.0)
            return np.array(out)

        try:
            res = least_squares(resid, z0, method='lm', max_nfev=200)
            zr = res.x
            return np.column_stack([zr[0::3], zr[1::3], zr[2::3]])
        except Exception:
            return None

    def graph_child(pA, pB):
        eA = contact_edges(pA)
        eB = contact_edges(pB)
        wA = wall_equalities(pA)
        wB = wall_equalities(pB)
        eA = list(eA); eB = list(eB)
        sel = []
        for e in eA:
            if rng.random() < 0.6:
                sel.append(e)
        for e in eB:
            if rng.random() < 0.6:
                sel.append(e)
        # union, dedupe
        sel = list(set(sel))
        sel = [e for e in sel if rng.random() >= 0.1]
        walls = list(set(wA + wB))
        seed = pA if score_of(pA) >= score_of(pB) else pB
        init = build_from_graph(sel, walls, seed)
        if init is None:
            return None
        # unweighted SLSQP maxiter=300
        pol = run_slsqp(init, ones, 300)
        if pol is None:
            return None
        c2 = pol.copy()
        c2[:, 2] -= 1e-9
        if not feasible(c2):
            return None
        return c2

    while time.process_time() < deadline:
        p1 = pop[tournament()]
        p2 = pop[tournament()]
        m = graph_child(p1, p2)
        if m is None:
            continue
        s = score_of(m)
        wi = int(np.argmin(scores))
        if s > scores[wi]:
            pop[wi] = m
            scores[wi] = s
            if s > best_score:
                best = m.copy()
                best_score = s

    # Final safety
    out = best.copy()
    out[:, 2] -= 1e-9
    if not feasible(out):
        out = relax(out, 50)
        out[:, 2] -= 1e-8
        if not feasible(out):
            if start is not None:
                out = np.array(start, dtype=float).copy()
                out[:, 2] -= 1e-8
    return out
